"""Independent wire fixtures, constructed from RFC field layouts, not Rust encoders."""
import json
import struct
from pathlib import Path
ROOT = Path(__file__).parent

def frame(kind, body):
    return b'\xff' * 16 + struct.pack('!HB', 19 + len(body), kind) + body

def opened(asn, router):
    return frame(1, struct.pack('!BHHIB', 4, 23456, 90, router, 8) + b'\x02\x06\x41\x04' + struct.pack('!I', asn))

def update(asn):
    attrs = bytes.fromhex('40010100 4002060201') + struct.pack('!I', asn) + bytes.fromhex('400304c0000202')
    return frame(2, b'\0\0' + struct.pack('!H', len(attrs)) + attrs + bytes.fromhex('18cb0071'))

def packet(seq, data, reverse=False, flags=0x18):
    src, dst = (b'\xc0\0\x02\x01', b'\xc0\0\x02\x02')
    sport, dport = 50000, 179
    if reverse:
        src, dst = dst, src
        sport, dport = dport, sport
    tcp = struct.pack('!HHIIBBHHH', sport, dport, seq, 0, 0x50, flags, 65535, 0, 0) + data
    ip = struct.pack('!BBHHHBBH4s4s', 0x45, 0, 20 + len(tcp), 0, 0x4000, 64, 6, 0, src, dst)
    return b'\0' * 12 + b'\x08\0' + ip + tcp

def pcap(packets):
    result = struct.pack('<IHHIIII', 0xa1b2c3d4, 2, 4, 0, 0, 65535, 1)
    for n, p in enumerate(packets):
        result += struct.pack('<IIII', 1700000000 + n, 0, len(p), len(p)) + p
    return result

a, b = opened(65536, 0xc0000201), opened(65537, 0xc0000202)
u = update(65536)
packets = [packet(1000, b'', flags=2), packet(2000, b'', True, 0x12), packet(1001, a), packet(2001, b, True),
           packet(1001 + len(a) + 20, u[20:]), packet(1001 + len(a), u[:20]),
           packet(1001 + len(a) + len(u), update(65538))]
(ROOT / 'session.pcap').write_bytes(pcap(packets))
(ROOT / 'midstream.pcap').write_bytes(pcap([packet(5000, u)]))
context = {'schema_version': 1, 'sessions': [{'flow': {'section': 0, 'interface': 0, 'source': '192.0.2.1', 'source_port': 50000,
    'destination': '192.0.2.2', 'destination_port': 179}, 'asn_width': 4, 'add_path': [], 'first_bgp_sequence': 5000}]}
(ROOT / 'session-context.json').write_text(json.dumps(context, indent=2) + '\n')

def block(kind, body):
    body += b'\0' * (-len(body) % 4)
    n = len(body) + 12
    return struct.pack('<II', kind, n) + body + struct.pack('<I', n)
ng = block(0x0a0d0d0a, struct.pack('<IHHq', 0x1a2b3c4d, 1, 0, -1))
for _ in range(2):
    ng += block(1, struct.pack('<HHI', 1, 0, 65535))
for n, p in enumerate(packets):
    stamp = (1700000000 + n) * 1000000
    ng += block(6, struct.pack('<IIIII', 1, stamp >> 32, stamp & 0xffffffff, len(p), len(p)) + p)
(ROOT / 'session.pcapng').write_bytes(ng)
records = []
peer = bytes.fromhex('c0000201 0000 0001 02 c0000202 c0000202 00010000')
rib = bytes.fromhex('00000001 18 cb0071 0001 0000 00000001 000d 40010100 400206020100010000')
for subtype, body in [(1, peer), (2, rib)]:
    records.append(struct.pack('!IHHI', 1700000000, 13, subtype, len(body)) + body)
(ROOT / 'routes.mrt').write_bytes(b''.join(records))
(ROOT / 'README.md').write_text('''# Independent passive-analysis fixtures

Generated by `generate.py` from explicit RFC field layouts, without using the Rust codec.
`session.pcap` and `session.pcapng` contain two four-octet OPENs, an out-of-order UPDATE,
and an origin change. PCAPNG uses interface 1 of two declared interfaces.
`midstream.pcap` requires the supplied context (JSON is valid YAML).
`routes.mrt` contains a TABLE_DUMP_V2 peer index and one IPv4 RIB entry.
IP/TCP checksums are zero, as can occur with capture offload; checksum validation is not asserted.
''')

def linked_pcap(link, values):
    result = struct.pack('<IHHIIII', 0xa1b2c3d4, 2, 4, 0, 0, 65535, link)
    for n, value in enumerate(values):
        result += struct.pack('<IIII', 1700000000 + n, 0, len(value), len(value)) + value
    return result

for name, link, values in [
    ('raw-ipv4', 101, [p[14:] for p in packets]),
    ('vlan', 1, [p[:12] + bytes.fromhex('810000010800') + p[14:] for p in packets]),
    ('sll', 113, [bytes.fromhex('00000001000600000000000000000800') + p[14:] for p in packets]),
    ('sll2', 276, [bytes.fromhex('0800000000000001000100060000000000000000') + p[14:] for p in packets]),
]:
    (ROOT / f'{name}.pcap').write_bytes(linked_pcap(link, values))
v6 = []
for p in packets:
    tcp = p[34:]
    src = bytes.fromhex('20010db8000000000000000000000001')
    dst = bytes.fromhex('20010db8000000000000000000000002')
    if struct.unpack('!H', tcp[:2])[0] == 179:
        src, dst = dst, src
    v6.append(struct.pack('!IHBB', 0x60000000, len(tcp), 6, 64) + src + dst + tcp)
(ROOT / 'raw-ipv6.pcap').write_bytes(linked_pcap(229, v6))
